from dynamodb.entity.todo_list.todo_list_entity import TodoListEntity
from dynamodb.entity.todo_list.todo_list_entity_repo import (
    TodoListEntityRepo,
    TodoListQueryResponse,
)
from dynamodb.entity.todo_list.todo_list_entity_service import TodoListEntityService


class TodoListService:

    def __init__(self):
        self.entity_service = TodoListEntityService(TodoListEntityRepo())

    def put_todo_list(self, todo_list: TodoListEntity) -> TodoListEntity:
        return self.entity_service.put_todo_list(todo_list=todo_list)

    def find_all_todo_lists(self, next_token: str, limit: int) -> TodoListQueryResponse:
        return self.entity_service.find_all_todo_lists(
            next_token=next_token, limit=limit
        )
